<?php require __DIR__.'/bootstrap.php';admin();$users=db()->query('SELECT u.id,u.name,u.email,u.role,u.created_at,(SELECT COUNT(*) FROM orders o WHERE o.user_id=u.id) AS order_count FROM users u ORDER BY u.created_at DESC LIMIT 500')->fetchAll();layout('Users','users.php');?><section class="panel"><div class="panelhead"><h2>Registered accounts</h2><span class="muted">Latest 500 · Read-only</span></div><div class="tablewrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Orders</th><th>Joined</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td><span class="status"><?=e($u['role'])?></span></td><td><?=e($u['order_count'])?></td><td><?=e($u['created_at'])?></td></tr><?php endforeach;?></tbody></table></div><p class="muted">Account role changes and deletion are intentionally disabled until audited admin-management workflows are added.</p></section><?php endLayout();
